<script setup>
import { computed, reactive, ref, onMounted, onUnmounted } from 'vue';
import { Head, Link, router } from '@inertiajs/vue3';
import { Search, ChevronDown, Sparkles, Layers3, X, Heart, Menu, ArrowRight, PackageSearch } from 'lucide-vue-next';
import ProductCard from '../../Components/ProductCard.vue';
import FilterSidebar from '../../Components/FilterSidebar.vue';
const props=defineProps({products:Object,relatedProducts:Array,categories:Array,locations:Array,filters:Object});
const q=ref(props.filters.query||''); const mobileFilters=ref(false); const isLoading=ref(false); const saved=ref(JSON.parse(localStorage.getItem('source-x-saved')||'[]'));
const filters=reactive({category:props.filters.category||'',location:props.filters.location||'',min:props.filters.min??'',max:props.filters.max??'',availability:props.filters.availability||'',sort:props.filters.sort||'relevance'});
const hasQuery=computed(()=>q.value.trim().length>0); const saveProduct=id=>{saved.value=saved.value.includes(id)?saved.value.filter(x=>x!==id):[...saved.value,id];localStorage.setItem('source-x-saved',JSON.stringify(saved.value));};
const search=()=>router.get('/',{q:q.value,...filters},{preserveState:true,replace:true});
let removeStart, removeFinish; onMounted(()=>{removeStart=router.on('start',()=>isLoading.value=true);removeFinish=router.on('finish',()=>isLoading.value=false)}); onUnmounted(()=>{removeStart?.();removeFinish?.()}); const reset=()=>{Object.assign(filters,{category:'',location:'',min:'',max:'',availability:'',sort:'relevance'});q.value='';search()}; const apply=()=>{mobileFilters.value=false;search()}; const chip=(key,value)=>{filters[key]=value;search()};
</script>
<template><Head title="Smart Product Discovery"/><div class="app-shell"><header class="topbar"><div class="container nav"><Link href="/" class="brand"><span class="brand-mark">SX</span><span>Source X</span></Link><div class="nav-label">Smart Product Discovery</div><div class="saved-count"><Heart :size="16"/> {{saved.length}} saved</div></div></header><main><section class="hero"><div class="container"><p class="kicker"><Sparkles :size="15"/> INTELLIGENT DISCOVERY</p><h1>Find products that fit <span>your need.</span></h1><p class="hero-copy">Search beyond keywords. Discover relevant products by category, location, price and availability.</p><div class="search-box"><Search :size="21"/><input v-model="q" @keyup.enter="search" placeholder="Try “মধু”, organic food, rice..."/><button @click="search">{{isLoading?'Searching…':'Search'}}</button></div><div class="quick-chips"><span>Popular:</span><button @click="q='মধু';search()">মধু</button><button @click="q='organic';search()">Organic</button><button @click="q='rice';search()">Rice</button><button @click="q='Manikganj';search()">Manikganj</button></div></div></section><section class="container discovery-layout"><button class="mobile-filter-toggle" @click="mobileFilters=true"><Menu :size="17"/> Filters</button><div v-if="mobileFilters" class="mobile-filter-overlay" @click.self="mobileFilters=false"><FilterSidebar :categories="categories" :locations="locations" :filters="filters" @apply="apply" @reset="reset"/><button class="close-filter" @click="mobileFilters=false"><X/></button></div><FilterSidebar class="desktop-filter" :categories="categories" :locations="locations" :filters="filters" @apply="apply" @reset="reset"/><div class="results-area"><div class="results-top"><div><div class="result-title">{{hasQuery?`Results for “${q}”`:'Discover products'}}</div><p>{{products.total}} products matching your criteria</p></div><label class="sort">Sort by<select v-model="filters.sort" @change="search"><option value="relevance">Relevance</option><option value="rating">Top rated</option><option value="price_low">Price: low to high</option><option value="price_high">Price: high to low</option><option value="newest">Newest</option></select><ChevronDown :size="15"/></label></div><div v-if="hasQuery||filters.category||filters.location||filters.availability||filters.min||filters.max" class="active-filters"><span>Active:</span><button v-if="hasQuery" @click="q='';search()">{{q}} <X :size="13"/></button><button v-if="filters.category" @click="chip('category','')">{{filters.category}} <X :size="13"/></button><button v-if="filters.location" @click="chip('location','')">{{filters.location}} <X :size="13"/></button><button v-if="filters.availability" @click="chip('availability','')">{{filters.availability==='available'?'In stock':'Out of stock'}} <X :size="13"/></button></div><div v-if="products.data.length" class="product-grid"><ProductCard v-for="product in products.data" :key="product.id" :product="product" :saved="saved.includes(product.id)" @toggle-save="saveProduct"/></div><div v-else class="empty-state"><div class="empty-icon"><PackageSearch/></div><h2>No matching products</h2><p>Try a broader search or clear a filter to discover more products.</p><button @click="reset">Clear all filters</button></div><div v-if="products.data.length&&products.last_page>1" class="pagination"><Link v-for="link in products.links" :key="link.label" :href="link.url||'#'" :class="{active:link.active,disabled:!link.url}" preserve-scroll v-html="link.label"/></div></div></section><section v-if="relatedProducts.length" class="related-section"><div class="container"><div class="section-heading"><div><p class="kicker"><Layers3 :size="15"/> DISCOVER MORE</p><h2>{{hasQuery?'Related to your search':'Recommended for discovery'}}</h2></div><Link href="/" class="section-link">Explore all <ArrowRight :size="16"/></Link></div><div class="product-grid related-grid"><ProductCard v-for="product in relatedProducts" :key="product.id" :product="product" :saved="saved.includes(product.id)" @toggle-save="saveProduct"/></div></div></section></main><footer><div class="container"><strong>Source X</strong><span>Smart Product Discovery Prototype · Laravel 12 · Vue 3 · Inertia.js</span></div></footer></div></template>
